Here is a simple C++ program that finds the nth Fibonacci number using recursion:

```cpp
#include <iostream>

using namespace std;

int fibonacci(int n) {
    //base case
    if (n == 0 || n == 1) {
        return 0;
    }

    //recursive case
    else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

int main() {
    // example 1
    cout << "The first 10 Fibonacci numbers are: " << endl;
    cout << fibonacci(10) << endl;

    // example 2
    cout << "The first 100 Fibonacci numbers are: " << endl;
    for (int i = 1; i <= 100; i++) {
        cout << fibonacci(i) << " ";
    }
    cout << endl;

    return 0;
}
```

This program uses `fibonacci` function to find the nth Fibonacci number recursively. The base case is if `n` is equal to 0 or 1, then return 0, otherwise call the function with the previous two values, add them together, return the result, and the recursive case is when `n` is not equal to 0 or 1, then call the function with the previous two values and return the result.</s>

Here is a C++ program that finds the nth number using the Fibonacci series:

```cpp
#include <iostream>

using namespace std;

int fibonacci(int n) {
    if (n <= 2) {
        return n;
    }
    else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

int fibonacci_sequence(int n) {
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += fibonacci(i + 2);
    }
    return result;
}

int main() {
    // example 1
    cout << "The first 10 Fibonacci numbers are: " << endl;
    cout << fibonacci_sequence(10) << endl;

    // example 2
    cout << "The first 100 Fibonacci numbers are: " << endl;
    for (int i = 1; i <= 100; i++) {
        cout << fibonacci_sequence(i) << " ";
    }
